const REGION_NAMES=Object.freeze({'서울':'서울특별시','부산':'부산광역시','대구':'대구광역시','인천':'인천광역시','광주':'광주광역시','대전':'대전광역시','울산':'울산광역시','세종':'세종특별자치시','세종시':'세종특별자치시','경기':'경기도','강원':'강원특별자치도','강원도':'강원특별자치도','충북':'충청북도','충남':'충청남도','전북':'전북특별자치도','전라북도':'전북특별자치도','전남':'전라남도','경북':'경상북도','경남':'경상남도','제주':'제주특별자치도','제주도':'제주특별자치도'});
function formatAddress(value){return String(value||'').trim().replace(/^(\S+)(?=\s|$)/,name=>REGION_NAMES[name]||name);}
function get(course){
 const r=addresses[String(course?.id||'')];if(!r)return null;
 const point=Array.isArray(course.path)&&course.path.length?course.path[0]:[Number(course.lat),Number(course.lng)];
 return point&&Math.abs(Number(point[0])-r.lat)<.00001&&Math.abs(Number(point[1])-r.lng)<.00001?{...r,address:formatAddress(r.address),roadAddress:formatAddress(r.roadAddress),parcelAddress:formatAddress(r.parcelAddress)}:null;
}
function normalize(value){return String(value||'').toLowerCase().replace(/서울특별시/g,'서울').replace(/(부산|대구|인천|광주|대전|울산)광역시/g,'$1').replace(/세종특별자치시/g,'세종').replace(/경기도/g,'경기').replace(/강원특별자치도|강원도/g,'강원').replace(/충청북도/g,'충북').replace(/충청남도/g,'충남').replace(/전북특별자치도|전라북도/g,'전북').replace(/전라남도/g,'전남').replace(/경상북도/g,'경북').replace(/경상남도/g,'경남').replace(/제주특별자치도|제주도/g,'제주').replace(/\s+/g,' ').trim();}
function matches(course,query,description=''){
 const r=get(course),hay=normalize([course.name,description,(course.tags||[]).join(' '),r?.address,r?.roadAddress,r?.parcelAddress].filter(Boolean).join(' '));
 return normalize(query).split(/\s+/).filter(Boolean).every(term=>hay.includes(term));
}
